def fair_candy_swap(alice_sizes, bob_sizes):
 difference=(sum(alice_sizes)-sum(bob_sizes))//2;bob=set(bob_sizes)
 return min(([value,value-difference] for value in alice_sizes if value-difference in bob),default=[])

